public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }
    int count = 0;
    long year = Y;
    while (year <= Integer.MAX_VALUE) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            count++;
            if (count == N) {
                return (int) year;
            }
        }
        year++;
    }
    // If we reach here, no such leap year within int range
    return -1;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) return result;
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, result);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // If any string is null or empty, no non‑empty substring can satisfy the condition
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
    }
    // Pre‑compute all substrings for each string
    List<Set<String>> substringSets = new ArrayList<>();
    for (String s : strings) {
        Set<String> set = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }
    String first = strings.get(0);
    int firstLen = first.length();
    // Iterate over possible lengths from longest to shortest
    for (int l = firstLen; l >= 1; l--) {
        for (int i = 0; i <= firstLen - l; i++) {
            String candidate = first.substring(i, i + l);
            String rev = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (Set<String> set : substringSets) {
                if (!set.contains(candidate) && !set.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return l;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int count = 0;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        if (grid[i] == null) {
            visited[i] = new boolean[0];
            continue;
        }
        visited[i] = new boolean[grid[i].length];
    }
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) continue;
        int cols = grid[r].length;
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                // BFS to mark all connected '@'
                java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
                queue.add(new int[]{r, c});
                visited[r][c] = true;
                while (!queue.isEmpty()) {
                    int[] pos = queue.poll();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && grid[nr] != null && nc >= 0 && nc < grid[nr].length) {
                            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                visited[nr][nc] = true;
                                queue.add(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return count;
}

