public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) throw new IllegalArgumentException("n must be positive");
    if (start == null || end == null) throw new IllegalArgumentException("start and end cannot be null");
    if (start.length != n || end.length != n) throw new IllegalArgumentException("start and end must have length n");
    if (paths == null) throw new IllegalArgumentException("paths cannot be null");
    if (java.util.Arrays.equals(start, end)) return "can be travelled";

    java.util.function.Function<int[], String> coordToKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    java.util.Map<String, java.util.Set<String>> adj = new java.util.HashMap<>();
    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);
    adj.putIfAbsent(startKey, new java.util.HashSet<>());
    adj.putIfAbsent(endKey, new java.util.HashSet<>());

    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            throw new IllegalArgumentException("Each path must have length 2*n");
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String keyA = coordToKey.apply(a);
        String keyB = coordToKey.apply(b);
        adj.computeIfAbsent(keyA, k -> new java.util.HashSet<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.HashSet<>()).add(keyA);
    }

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.Set<String> neighbors = adj.getOrDefault(cur, java.util.Collections.emptySet());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return "Invalid date";
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "Invalid date";
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        String monthName = localDate.getMonth()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String weekday = localDate.getDayOfWeek()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (Exception e) {
        return "Invalid date";
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        return new int[]{-1, -1};
    }
    java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        Integer prevIndex = map.get(complement);
        if (prevIndex != null) {
            return new int[]{prevIndex, i};
        }
        map.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

