public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[k - r]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }
    @SuppressWarnings("unchecked")
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length < 2) continue;
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }
    boolean[] visited = new boolean[n];
    int[] time = new int[1];
    dfs(0, graph, visited, hasApple, time);
    return time[0];
}

private boolean dfs(int node, List<Integer>[] graph, boolean[] visited, boolean[] hasApple, int[] time) {
    visited[node] = true;
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (!visited[nei]) {
            boolean childHas = dfs(nei, graph, visited, hasApple, time);
            if (childHas) {
                time[0] += 2;
                has = true;
            }
        }
    }
    return has;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        // Ascending pass: pick smallest available characters
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
        // Descending pass: pick largest available characters
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k][s] == true if a subset of size k with sum s exists
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k backwards to avoid reuse of the same element
        for (int k = n - 1; k >= 0; k--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // You can start at step 1 (top) with no cost
        return 0;
    }
    int prev2 = cost[0]; // cost to reach step 0
    int prev1 = cost[1]; // cost to reach step 1
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int uniqueMorseRepresentations(String[] words) {
