            }
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int total = 1 << k;
    if (s.length() < total) {
        return false;
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    // Build the first code of length k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;
    // Slide over the string
    for (int i = k; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) {
                return true;
            }
        }
    }
    return count == total;
}

