public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0) {
        return result;
    }
    // Use long to avoid overflow during generation
    Queue<Long> queue = new LinkedList<>();
    // Start BFS from digits 0-9
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        // Do not extend numbers that start with 0
        if (num == 0) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        count += higher * factor;
        if (cur == 1) {
            count += lower + 1;
        } else if (cur > 1) {
            count += factor;
        }
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int cur = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                   Math.max(diag[i][j], anti[i][j]));
                if (cur > max) {
                    max = cur;
                }
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long num = Math.abs((long) n); // use long to avoid overflow for Integer.MIN_VALUE
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (num > 0) {
        sb.append(num % 10);
        num /= 10;
        digitCount++;
        if (num > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    // Precompute which pairs sum to a perfect square
    boolean[][] canPair = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            canPair[i][j] = (r * r == sum);
        }
    }
    // DP memoization: dp[mask][last] = number of ways to finish
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(dp[i], -1L);
    }
    // Recursive helper using a local class
    class Solver {
        long dfs(int mask, int last) {
            if (mask == (1 << n) - 1) return 1L;
            if (dp[mask][last] != -1L) return dp[mask][last];
            long count = 0L;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!canPair[last][next]) continue;
                // Skip duplicates: if next > 0, same value as previous and previous not used
                if (next > 0 && A[next] == A[next - 1] && (mask & (1 << (next - 1))) == 0) continue;
                count += dfs(mask | (1 << next), next);
            }
            dp[mask][last] = count;
            return count;
        }
    }
    Solver solver = new Solver();
    long total = 0L;
    for (int start = 0; start < n; start++) {
        // Skip duplicates for the first element
        if (start > 0 && A[start] == A[start - 1] && (0 & (1 << (start - 1))) == 0) continue;
        total += solver.dfs(1 << start, start);
    }
    return (int) total;
}

