public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (top >= 0 && h < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int i = 0, j = 0;
    boolean up = true; // true for up-right, false for down-left
    while (index < result.length) {
        result[index++] = mat[i][j];
        if (up) {
            if (j == n - 1) { // hit right boundary
                i++;
                up = false;
            } else if (i == 0) { // hit top boundary
                j++;
                up = false;
            } else {
                i--;
                j++;
            }
        } else { // moving down-left
            if (i == m - 1) { // hit bottom boundary
                j++;
                up = true;
            } else if (j == 0) { // hit left boundary
                i++;
                up = true;
            } else {
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no larger permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    long result = Long.parseLong(new String(digits));
    if (result > Integer.MAX_VALUE) {
        return -1; // cannot fit in int
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    Map<Integer, List<String>> memo = new HashMap<>();
    List<String> base = new ArrayList<>();
    base.add("");
    memo.put(0, base);
    for (int len = 2; len <= n; len++) {
        List<String> cur = new ArrayList<>();
        List<String> prev = memo.get(len - 2);
        for (String s : prev) {
            if (len != n) {
                cur.add("0" + s + "0");
            }
            cur.add("1" + s + "1");
            cur.add("6" + s + "9");
            cur.add("8" + s + "8");
            cur.add("9" + s + "6");
        }
        memo.put(len, cur);
    }
    return memo.get(n);
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check for duplicate points
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];
    long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    for (int i = 1; i < n; i++) {
        long next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = (int) next;
        if (next == next2) {
            i2++;
            next2 = (long) ugly[i2] * 2;
        }
        if (next == next3) {
            i3++;
            next3 = (long) ugly[i3] * 3;
        }
        if (next == next5) {
            i5++;
            next5 = (long) ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    return Math.max(maxLen, currentLen);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n <= 0) {
        return result;
    }
    Deque<Long> stack = new ArrayDeque<>();
    for (int i = 9; i >= 1; i--) {
        if (i <= n) {
            stack.push((long) i);
        }
    }
    while (!stack.isEmpty()) {
        long current = stack.pop();
        result.add((int) current);
        for (int i = 9; i >= 0; i--) {
            long next = current * 10 + i;
            if (next <= n) {
                stack.push(next);
            }
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < min) {
                min = dp[i - square] + 1;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());
    return result.toString();
}
